import std.concurrent as conc

pub type AppError = Failed(String)

pub fn main() -> Result<(), AppError> {
    let queue = conc.Mutex(0)
    let notEmpty = conc.Cond(queue)
    notEmpty.wait(|v| v > 0)
    notEmpty.signal()
    notEmpty.broadcast()
    let dbLimiter = conc.Semaphore(10)
    dbLimiter.acquire()
    dbLimiter.release()
    let n = dbLimiter.currentCount()
    let ok = dbLimiter.tryAcquire()
    let _ = n
    let _ = ok
    return Ok(())
}

